// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 recipientBalanceBefore = recipient.balance;
        bool ok;
        try c.withdrawAll(recipient) { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 recipientBalanceAfter = recipient.balance;
            assertTrue(recipientBalanceAfter == recipientBalanceBefore + amount);
        }
    }
}
